36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    @Column(name = "title")
41	    private String title;
42	
43	    @Column(name = "address")
44	    @NotEmpty
45	    private String address;
46	
47	    @Column(name = "address_line1")
48	    private String addressLine1;
49	
50	    @Column(name = "address_line2")
51	    private String addressLine2;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    @Email
64	    private String email;
65	
66	    @Column(name = "postcode")
67	    private String postcode;
68	
69	    @Column(name = "registration_date")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "birth_date")
73	    private LocalDate birthDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "membership_number")
85	    private String membershipNumber;
86	
87	    @Column(name = "bulk_signup_warning")
88	    private Boolean bulkSignupWarning;
89	
90	    @Column(name = "household_size")
91	    private Integer householdSize;
92	
93	    @Column(name = "possible_duplicate")
94	    private Boolean possibleDuplicate;
95	
96	    @Column(name = "possible_duplicate_of")
97	    private Integer possibleDuplicateOf;
98	
99	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
100	    private Set<Pet> pets;
101	
102	    public String getTitle() {
103	        return this.title;
104	    }
105	
106	    public void setTitle(String title) {
107	        this.title = title;
108	    }
109	
110	    /**
111	     * The owner's salutation, composed from its {@link #getTitle() title} and
112	     * {@link #getLastName() last name}: {@code title + ' ' + lastName} when a title is
113	     * present, or just the last name when no title was supplied. Derived (not persisted);
114	     * recomputed each call. See {@link OwnerDerivations#salutation(String, String)}.
115	     *
116	     * @return the composed salutation
117	     */
118	    @Transient
119	    public String getSalutation() {
120	        return OwnerDerivations.salutation(this.title, this.getLastName());
121	    }
122	
123	    public String getAddress() {
124	        return this.address;
125	    }
126	
127	    public void setAddress(String address) {
128	        this.address = address;
129	    }
130	
131	    public String getAddressLine1() {
132	        return this.addressLine1;
133	    }
134	
135	    public void setAddressLine1(String addressLine1) {
136	        this.addressLine1 = addressLine1;
137	    }
138	
139	    public String getAddressLine2() {
140	        return this.addressLine2;
141	    }
142	
143	    public void setAddressLine2(String addressLine2) {
144	        this.addressLine2 = addressLine2;
145	    }
146	
147	    public String getCity() {
148	        return this.city;
149	    }
150	
151	    public void setCity(String city) {
152	        this.city = city;
153	    }
154	
155	    /**
156	     * The owner's locality, i.e. the canonical region it belongs to (read from the
157	     * assigned {@link #customerCode} when present, otherwise derived from the owner's
158	     * own fields via {@link #regionForOwner()}). Derived (not persisted); recomputed
159	     * each call. See {@link OwnerDerivations#locality(String, String, String)} for the
160	     * full derivation.
161	     *
162	     * @return the canonical region string, or {@code "UNKNOWN"}
163	     */
164	    @Transient
165	    public String getLocality() {
166	        return OwnerDerivations.locality(this.customerCode, this.postcode, this.city);
167	    }
168	
169	    /**
170	     * The canonical region derived for this owner from its own fields. Recomputed each
171	     * call. See {@link OwnerDerivations#region(String, String)} for the derivation.
172	     *
173	     * @return the canonical region string, or {@code "UNKNOWN"}
174	     */
175	    public String regionForOwner() {
176	        return OwnerDerivations.region(this.postcode, this.city);
177	    }
178	
179	    /**
180	     * The owner's IANA timezone name, derived from its {@link #getLocality() locality}
181	     * (canonical region) via the fixed region-to-timezone table. Derived (not persisted);
182	     * recomputed each call and {@code null} when the locality is not a known region. See
183	     * {@link OwnerDerivations#timezone(String)} for the derivation.
184	     *
185	     * @return the IANA timezone name, or {@code null}
186	     */
187	    @Transient
188	    public String getTimezone() {
189	        return OwnerDerivations.timezone(this.getLocality());
190	    }
191	
192	    /**
193	     * Whether this owner's postcode is consistent with its {@link #getLocality()
194	     * locality}: an absent postcode is accepted, a present one must be exactly four
195	     * digits and, when the locality has a known postcode range, fall within it. See
196	     * {@link OwnerDerivations#postcodeMatchesRegion(String, String)}.
197	     *
198	     * @return {@code true} if the postcode is absent or valid for the owner's locality
199	     */
200	    public boolean postcodeValidForLocality() {
201	        return OwnerDerivations.postcodeMatchesRegion(this.postcode, this.getLocality());
202	    }
203	
204	    /**
205	     * The owner's membership points, a non-negative score derived from its factors.
206	     * Derived (not persisted); recomputed from the current fields each call, so it rises
207	     * once the owner's tenure since {@link #registrationDate} exceeds 365 days. See
208	     * {@link OwnerDerivations#membershipPoints(String, Integer, Integer, LocalDate, LocalDate)}
209	     * for how it is scored.
210	     *
211	     * @return the membership points, 0 or more
212	     */
213	    @Transient
214	    public Integer getMembershipPoints() {
215	        return OwnerDerivations.membershipPoints(this.email, this.namesakeCount, this.householdSize,
216	            this.registrationDate, LocalDate.now());
217	    }
218	
219	    /**
220	     * The owner's membership level, a number from 1 to 4, mapped from its
221	     * {@link #getMembershipPoints() membership points}. Derived (not persisted);
222	     * recomputed from the current fields each call, so it rises to level 4 once the
223	     * owner's tenure since {@link #registrationDate} exceeds 365 days. See
224	     * {@link OwnerDerivations#membershipLevel(int)} for the mapping.
225	     *
226	     * @return the membership level, from 1 to 4
227	     */
228	    @Transient
229	    public Integer getMembershipLevel() {
230	        return OwnerDerivations.membershipLevel(getMembershipPoints());
231	    }
232	
233	    /**
234	     * The owner's preferred contact channel, {@code "EMAIL"} or {@code "PHONE"}.
235	     * Derived (not persisted); recomputed from the current fields each call. See
236	     * {@link OwnerDerivations#contactPreference(String)}.
237	     *
238	     * @return {@code "EMAIL"} or {@code "PHONE"}
239	     */
240	    @Transient
241	    public String getContactPreference() {
242	        return OwnerDerivations.contactPreference(this.email);
243	    }
244	
245	    public String getTelephone() {
246	        return this.telephone;
247	    }
248	
249	    /**
250	     * The stored E.164 {@link #telephone} formatted for humans: a leading '+'
251	     * and country code, a space, then the national digits grouped in threes
252	     * (e.g. {@code "+61 412 345 678"}). Derived (not persisted); recomputed each
253	     * call and {@code null} when no telephone is present. See
254	     * {@link Telephones#toDisplay(String)} for the exact format.
255	     *
256	     * @return the human-formatted telephone, or {@code null} when absent
257	     */
258	    @Transient
259	    public String getTelephoneDisplay() {
260	        return Telephones.toDisplay(this.telephone);
261	    }
262	
263	    public void setTelephone(String telephone) {
264	        this.telephone = telephone;
265	    }
266	
267	    public String getEmail() {
268	        return this.email;
269	    }
270	
271	    public void setEmail(String email) {
272	        this.email = email;
273	    }
274	
275	    public String getPostcode() {
276	        return this.postcode;
277	    }
278	
279	    public void setPostcode(String postcode) {
280	        this.postcode = postcode;
281	    }
282	
283	    public LocalDate getRegistrationDate() {
284	        return this.registrationDate;
285	    }
286	
287	    public void setRegistrationDate(LocalDate registrationDate) {
288	        this.registrationDate = registrationDate;
289	    }
290	
291	    public LocalDate getBirthDate() {
292	        return this.birthDate;
293	    }
294	
295	    public void setBirthDate(LocalDate birthDate) {
296	        this.birthDate = birthDate;
297	    }
298	
299	    /**
300	     * The owner's age band, {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"},
301	     * derived from {@link #birthDate} measured against {@link #registrationDate}.
302	     * Derived (not persisted); recomputed each call and {@code null} when no birth
303	     * date has been supplied. See
304	     * {@link OwnerDerivations#ageBand(LocalDate, LocalDate)} for the derivation.
305	     *
306	     * @return the age band, or {@code null} when no birth date is present
307	     */
308	    @Transient
309	    public String getAgeBand() {
310	        return OwnerDerivations.ageBand(this.birthDate, this.registrationDate);
311	    }
312	
313	    public String getCustomerCode() {
314	        return this.customerCode;
315	    }
316	
317	    public void setCustomerCode(String customerCode) {
318	        this.customerCode = customerCode;
319	    }
320	
321	    /**
322	     * The Luhn check digit (0-9) computed over the digits in this owner's
323	     * {@link #customerCode}. Derived (not persisted); recomputed each call. See
324	     * {@link OwnerDerivations#checkDigit(String)}.
325	     *
326	     * @return the Luhn check digit, from 0 to 9
327	     */
328	    @Transient
329	    public Integer getCheckDigit() {
330	        return OwnerDerivations.checkDigit(this.customerCode);
331	    }
332	
333	    public String getHouseholdId() {
334	        return this.householdId;
335	    }
336	
337	    public void setHouseholdId(String householdId) {
338	        this.householdId = householdId;
339	    }
340	
341	    public Integer getNamesakeCount() {
342	        return this.namesakeCount;
343	    }
344	
345	    public void setNamesakeCount(Integer namesakeCount) {
346	        this.namesakeCount = namesakeCount;
347	    }
348	
349	    public String getMembershipNumber() {
350	        return this.membershipNumber;
351	    }
352	
353	    public void setMembershipNumber(String membershipNumber) {
354	        this.membershipNumber = membershipNumber;
355	    }
356	
357	    public Boolean getBulkSignupWarning() {
358	        return this.bulkSignupWarning;
359	    }
360	
361	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
362	        this.bulkSignupWarning = bulkSignupWarning;
363	    }
364	
365	    public Integer getHouseholdSize() {
366	        return this.householdSize;
367	    }
368	
369	    public void setHouseholdSize(Integer householdSize) {
370	        this.householdSize = householdSize;
371	    }
372	
373	    public Boolean getPossibleDuplicate() {
374	        return this.possibleDuplicate;
375	    }
376	
377	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
378	        this.possibleDuplicate = possibleDuplicate;
379	    }
380	
381	    public Integer getPossibleDuplicateOf() {
382	        return this.possibleDuplicateOf;
383	    }
384	
385	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
386	        this.possibleDuplicateOf = possibleDuplicateOf;
387	    }
388	
389	    /**
390	     * The derived key used for duplicate detection, combining this owner's normalised
391	     * telephone, email and {@link #householdId}. Two owners are duplicates exactly when
392	     * their whole identity keys are equal, so members of the same household with
393	     * different telephones have different keys. Derived (not persisted); recomputed each
394	     * call. See {@link OwnerDerivations#identityKey(String, String, String)} for the
395	     * exact format.
396	     *
397	     * @return the owner's identity key
398	     */
399	    @Transient
400	    public String getIdentityKey() {
401	        return OwnerDerivations.identityKey(this.telephone, this.email, this.householdId);
402	    }
403	
404	    /**
405	     * Compute the customer code to assign to this owner at creation, formatted
406	     * {@code <REGION>-<HASH8>} from the owner's (already normalised) fields. This is the
407	     * value stored in {@link #getCustomerCode()}; see
408	     * {@link OwnerDerivations#customerCode(String, String, String)} for the format.
409	     *
410	     * @return the customer code to assign
411	     */
412	    public String computeCustomerCode() {
413	        return OwnerDerivations.customerCode(regionForOwner(), this.telephone, this.getLastName());
414	    }
415	
416	    /**
417	     * Compute the stable household identifier for this owner, derived deterministically
418	     * from its last name and postcode so every owner sharing a last name and postcode
419	     * resolves to the same value. This is the value stored in {@link #getHouseholdId()};
420	     * see {@link OwnerDerivations#householdId(String, String)} for the exact derivation.
421	     *
422	     * @return the household identifier
423	     */
424	    public String computeHouseholdId() {
425	        return OwnerDerivations.householdId(normalize(this.getLastName()), this.postcode);
426	    }
427	
428	    /**
429	     * Whether this owner belongs to the same household as {@code other}: that is, they
430	     * share the same last name and postcode. The last name is compared
431	     * case-insensitively with runs of whitespace collapsed to a single space (and
432	     * surrounding whitespace trimmed); the postcode is compared for exact equality (two
433	     * absent postcodes count as equal). Owners in the same household resolve to the same
434	     * {@link #computeHouseholdId() household identifier}.
435	     *
436	     * @param other the owner to compare against
437	     * @return {@code true} if both owners share a household
438	     */
439	    public boolean sameHouseholdAs(Owner other) {
440	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
441	            && Objects.equals(this.postcode, other.postcode);
442	    }
443	
444	    /**
445	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
446	     * trim, collapse internal runs of whitespace to a single space and lower-case.
447	     */
448	    private static String normalize(String value) {
449	        return OwnerDerivations.collapseWhitespace(value).toLowerCase();
450	    }
451	
452	    /**
453	     * Reduce an address to its canonical stored form. This is the value stored,
454	     * returned and used for every household comparison; see
455	     * {@link OwnerDerivations#normalizeAddress(String)} for the exact normalisation.
456	     *
457	     * @param value the raw address (may be {@code null})
458	     * @return the normalised address, or the empty string if {@code value} is
459	     *         {@code null} or blank
460	     */
461	    public static String normalizeAddress(String value) {
462	        return OwnerDerivations.normalizeAddress(value);
463	    }
464	
465	    protected Set<Pet> getPetsInternal() {
466	        if (this.pets == null) {
467	            this.pets = new HashSet<>();
468	        }
469	        return this.pets;
470	    }
471	
472	    protected void setPetsInternal(Set<Pet> pets) {
473	        this.pets = pets;
474	    }
475	
476	    public List<Pet> getPets() {
477	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
478	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
479	        return Collections.unmodifiableList(sortedPets);
480	    }
481	
482	    public void setPets(List<Pet> pets) {
483	        this.pets = new HashSet<>(pets);
484	    }
485	
486	    public void addPet(Pet pet) {
487	        getPetsInternal().add(pet);
488	        pet.setOwner(this);
489	    }
490	
491	    /**
492	     * Return the Pet with the given name, or null if none found for this Owner.
493	     *
494	     * @param name to test
495	     * @return true if pet name is already in use
496	     */
497	    public Pet getPet(String name) {
498	        return getPet(name, false);
499	    }
500	
501	    /**
502	     * Return the Pet with the given name, or null if none found for this Owner.
503	     *
504	     * @param name to test
505	     * @return true if pet name is already in use
506	     */
507	    public Pet getPet(String name, boolean ignoreNew) {
508	        name = name.toLowerCase();
509	        for (Pet pet : getPetsInternal()) {
510	            if (!ignoreNew || !pet.isNew()) {
511	                String compName = pet.getName();
512	                compName = compName.toLowerCase();
513	                if (compName.equals(name)) {
514	                    return pet;
515	                }
516	            }
517	        }
518	        return null;
519	    }
520	
521	    public Pet getPet(Integer petId) {
522	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
523	    }
524	
525	    @Override
526	    public String toString() {
527	        return new ToStringCreator(this)
528	
529	            .append("id", this.getId())
530	            .append("new", this.isNew())
531	            .append("lastName", this.getLastName())
532	            .append("firstName", this.getFirstName())
533	            .append("address", this.address)
534	            .append("city", this.city)
535	            .append("telephone", this.telephone)
536	            .toString();
537	    }
538	}
